import React from "react";
import { Helmet } from "react-helmet";

function App() {
    return (
        <div>
            <Helmet>
                <title>My Sample Page</title>
                <meta name="description" content="This is a sample page using React Helmet." />
            </Helmet>
            <h1>Welcome to React Helmet POC</h1>
        </div>
    );
}

export default App;
